// src/components/BottomNavigation.js
import React, { useState } from 'react';
import {
  PlayIcon,
  ReplayIcon,
  SkipIcon,
  SelectRandomIcon,
  InteractiveOblongNavItem,
  AnimatedBorderButton,
  ViewSwitcherButton,
} from './uiElements';
import { DESIGN_CONTENT, QUIZZES, WHAT_DESIGN_NAV_ITEMS, DESIGN_VIEWS } from '../content';
import PropTypes from 'prop-types';


const BottomNavigation = ({
    navItems,
    activeNavItem,
    isPlaying,
    isFadingOut,
    isDarkMode,
    showLeftFade,
    showRightFade,
    onCentralButtonClick,
    onNavItemClick,
    scrollContainerRef,
    itemNavRefs,
    containerClass,
    navItemsFlexClass,
    currentChapter,
    design,
    work
}) => {
    const [isClicked, setIsClicked] = useState(false);

    const handleStaticButtonClick = () => {
        setIsClicked(true);
        onCentralButtonClick();
        setTimeout(() => setIsClicked(false), 400);
    };

    const renderCentralButton = () => {
        const isMainChapterFinalState = currentChapter === 'main' && activeNavItem === 'Home' && !isPlaying;

        const isWhatDesignFinished = currentChapter === 'design' &&
            design.designView === DESIGN_VIEWS.WHAT_DESIGN &&
            !isPlaying &&
            design.isDesignChapterFinished;

        // **THE FIX IS HERE**: Updated logic for "Why Design" states
        const isWhyDesignIntroDone = currentChapter === 'design' &&
            design.designView === DESIGN_VIEWS.WHY_DESIGN &&
            design.whyDesignIntroCompleted &&
            design.whyDesignStep === 'intro';

        const isWhyDesignGameActive = currentChapter === 'design' &&
            design.designView === DESIGN_VIEWS.WHY_DESIGN &&
            design.whyDesignStep === 'game' &&
            design.gameStatus === 'playing';

        const isWhyDesignBonus = currentChapter === 'design' &&
            design.designView === DESIGN_VIEWS.WHY_DESIGN &&
            design.gameStatus === 'bonus';

        const isWhyDesignResults = currentChapter === 'design' &&
            design.designView === DESIGN_VIEWS.WHY_DESIGN &&
            design.gameStatus === 'end';


        const showReplayButtonForChapters = isMainChapterFinalState || isWhatDesignFinished || isWhyDesignResults;
        const allQuizzesAnswered = QUIZZES.every(quiz => work.quizAnswers[quiz.id]?.correct);
        const isOnResultsPage = work.workView === 'Quiz' && work.workStepIndex > QUIZZES.length;

        const nonAnimatedButtonClasses = "group h-12 w-12 sm:h-[3.75rem] sm:w-[3.75rem] flex-shrink-0 flex items-center justify-center rounded-full shadow-md transition-all duration-200 focus:outline-none transform hover:scale-105 active:scale-95 bg-bg-base text-icon-interactive hover:text-icon-base ring-1 ring-gray-500 dark:ring-gray-700 focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-primary dark:focus-visible:ring-offset-slate-800";
        const iconAnimationClass = isClicked ? 'animate-click-bounce' : '';
        
        // Handle "Why Design" game's "Skip" state
        if (isWhyDesignGameActive) {
            const questionId = `${design.gameCaseIndex}-${design.gamePartIndex}`;
            const questionState = design.gameQuestionStates[questionId];
            if (!questionState?.completed) {
                return <button onClick={handleStaticButtonClick} className={nonAnimatedButtonClasses} aria-label="Skip question"><SkipIcon className={`w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-200 group-hover:scale-105 ${iconAnimationClass}`} /></button>;
            }
        }

         // Handle "Why Design" bonus cases
        if (isWhyDesignBonus) {
            return <button onClick={handleStaticButtonClick} className={nonAnimatedButtonClasses} aria-label="Select Random Bonus Case"><SelectRandomIcon className={`w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-200 group-hover:scale-105 ${iconAnimationClass}`} /></button>;
        }
        
        // Handle "Why Design" intro's "Play" state after animation
        if (isWhyDesignIntroDone) {
             return <button onClick={handleStaticButtonClick} className={nonAnimatedButtonClasses} aria-label="Start Game"><PlayIcon className={`w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-200 group-hover:scale-105 ${iconAnimationClass}`} /></button>;
        }

        if (currentChapter === 'work' && work.workView === 'Quiz' && !showReplayButtonForChapters) {
            let icon;
            let label = "Central control button";
            if (work.workStepIndex === 0) {
                icon = <PlayIcon className={`w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-200 group-hover:scale-105 ${iconAnimationClass}`} />;
                label = "Start quiz";
           } else if (isOnResultsPage) {
                icon = <ReplayIcon className={`w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-200 group-hover:scale-105 ${iconAnimationClass}`} />;
                label = "Replay quiz";
            } else {
                icon = <SkipIcon className={`w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-200 group-hover:scale-105 ${iconAnimationClass}`} />;
                label = "Skip question";
            }
            return <button onClick={handleStaticButtonClick} className={nonAnimatedButtonClasses} aria-label={label}>{icon}</button>;
        }

        if (showReplayButtonForChapters || (currentChapter === 'work' && (allQuizzesAnswered || isOnResultsPage))) {
            return (
                <button onClick={handleStaticButtonClick} className={nonAnimatedButtonClasses} aria-label="Replay chapter">
                    <ReplayIcon className={`w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-200 group-hover:scale-105 ${iconAnimationClass}`} />
                </button>
            );
        }
        
        return (
            <AnimatedBorderButton
                isPlaying={isPlaying}
                onClick={onCentralButtonClick}
                className="h-12 w-12 sm:h-[3.75rem] sm:w-[3.75rem] flex-shrink-0"
                aria-label={isPlaying ? 'Pause' : 'Play'}
            />
        );
    };

    if (currentChapter === 'work' && work.workView === 'Overview') {
    return (
        <div className="fixed bottom-0 left-0 w-full px-4 mb-6 z-20 flex justify-center">
            <div className={`relative w-auto max-w-full transform transition-transform duration-200 hover:scale-[1.02] bg-bg-muted dark:bg-slate-950 rounded-full shadow-lg border border-gray-500 dark:border-gray-700 overflow-hidden`}>
                <div
                    ref={scrollContainerRef}
                    className="py-1.5 px-2.5 flex items-center justify-start space-x-2 transition-colors duration-300 overflow-x-auto no-scrollbar"
                >
                    {work.PROJECT_NAV_ITEMS.map((item, index) => (
                        <InteractiveOblongNavItem
                            key={item.id}
                            ref={el => itemNavRefs.current[index] = el}
                            text={item.name}
                            onClick={() => onNavItemClick(item.id)}
                            isActive={activeNavItem === item.id}
                            isDarkMode={isDarkMode}
                        />
                    ))}
                </div>
                <div className={`absolute top-0 bottom-0 left-0 w-24 bg-gradient-to-r from-bg-muted to-transparent transition-opacity duration-300 ${showLeftFade ? 'opacity-100' : 'opacity-0'} pointer-events-none`}></div>
                <div className={`absolute top-0 bottom-0 right-[-0.1rem] w-24 bg-gradient-to-l from-bg-muted to-transparent transition-opacity duration-300 ${showRightFade ? 'opacity-100' : 'opacity-0'} pointer-events-none`}></div>
            </div>
        </div>
    );
}

    const isDesignDocumentView = currentChapter === 'design' && design.documentView === 'Document';
    const isLastDesignStage = design.activeDesignStageKey === WHAT_DESIGN_NAV_ITEMS[WHAT_DESIGN_NAV_ITEMS.length - 1].name;

    return (
        <div className="fixed bottom-0 left-0 w-full px-4 mb-6 z-20 flex justify-center">
            <div className={containerClass}>
                
                {isDesignDocumentView ? (
                    <button
                        onClick={isLastDesignStage ? design.replay : design.nextDesignStage}
                        className="group h-12 w-12 sm:h-[3.75rem] sm:w-[3.75rem] flex-shrink-0 items-center justify-center rounded-full shadow-md transition-all duration-200 focus:outline-none transform hover:scale-105 active:scale-95 bg-bg-base dark:bg-black text-icon-interactive hover:text-icon-base ring-1 ring-gray-500 dark:ring-gray-700 focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-primary dark:focus-visible:ring-offset-slate-800 hidden md:flex"
                        aria-label={isLastDesignStage ? "Replay Chapter" : "Next Section"}
                    >
                        {isLastDesignStage ? (
                            <ReplayIcon className="w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-200 group-hover:scale-105" />
                        ) : (
                            <SkipIcon className="w-5 h-5 sm:w-6 sm:h-6 transition-transform duration-200 group-hover:scale-105" />
                        )}
                    </button>
                ) : (
                    renderCentralButton()
                )}
                
                <div className={`relative ${navItemsFlexClass} transform transition-transform duration-200 hover:scale-[1.0125] bg-bg-muted dark:bg-slate-950 rounded-full shadow-lg border border-gray-500 dark:border-gray-700 overflow-hidden`}>
                    <div
                        ref={scrollContainerRef}
                        className="py-1.5 px-2 flex items-center space-x-1 transition-colors duration-300 overflow-x-auto no-scrollbar"
                    >
                        {navItems.map((item, index) => {
                            let navItemText = (currentChapter === 'design' && design.designView === DESIGN_VIEWS.WHAT_DESIGN && DESIGN_CONTENT[item.name])
                                ? DESIGN_CONTENT[item.name].navText
                                : item.name;
                            let navIdentifier = item.name;
                            if (currentChapter === 'work' && work.workView === 'Quiz' && item.name.startsWith('Question')) {
                                const quizIndex = index - 1;
                                if (quizIndex >= 0 && quizIndex < QUIZZES.length) {
                                    const quiz = QUIZZES[quizIndex];
                                    if (work.quizAnswers[quiz.id]?.correct) {
                                        navItemText = `${quiz.title} ✓`;
                                        navIdentifier = quiz.title;
                                    }
                                }
                            }

                            const isPlayingForNavItem = isDesignDocumentView ? false
                                : (activeNavItem === navIdentifier && isPlaying && !isFadingOut);

                            return (
                                <InteractiveOblongNavItem
                                    key={`${currentChapter}-${design.designView}-${item.name}`}
                                    ref={el => itemNavRefs.current[index] = el}
                                    text={navItemText}
                                    onClick={() => onNavItemClick(navIdentifier)}
                                    isActive={activeNavItem === navIdentifier || activeNavItem === item.name}
                                    isPlaying={isPlayingForNavItem}
                                    isFadingOut={activeNavItem === navIdentifier && isFadingOut}
                                    isDarkMode={isDarkMode}
                                />
                            );
                        })}
                    </div>
                    <div className={`absolute top-0 bottom-0 left-0 w-24 bg-gradient-to-r from-[var(--color-bg-muted)] to-transparent transition-opacity duration-300 ${showLeftFade ? 'opacity-100' : 'opacity-0'} pointer-events-none`}></div>
                    <div className={`absolute top-0 bottom-0 right-[-0.1rem] w-24 bg-gradient-to-l from-[var(--color-bg-muted)] to-transparent transition-opacity duration-300 ${showRightFade ? 'opacity-100' : 'opacity-0'} pointer-events-none`}></div>
                </div>
                {currentChapter === 'design' && design.designView === DESIGN_VIEWS.WHAT_DESIGN && (
                    <ViewSwitcherButton
                        currentView={design.documentView}
                        onClick={design.toggleDocumentView}
                        isDarkMode={isDarkMode}
                    />
                )}
            </div>
        </div>
    );
};

BottomNavigation.propTypes = {
  navItems: PropTypes.array.isRequired,
  activeNavItem: PropTypes.string,
  isPlaying: PropTypes.bool.isRequired,
  isFadingOut: PropTypes.bool,
  isDarkMode: PropTypes.bool.isRequired,
  showLeftFade: PropTypes.bool.isRequired,
  showRightFade: PropTypes.bool.isRequired,
  onCentralButtonClick: PropTypes.func.isRequired,
  onNavItemClick: PropTypes.func.isRequired,
  scrollContainerRef: PropTypes.object.isRequired,
  itemNavRefs: PropTypes.object.isRequired,
  containerClass: PropTypes.string.isRequired,
  navItemsFlexClass: PropTypes.string.isRequired,
  currentChapter: PropTypes.string.isRequired,
  design: PropTypes.object.isRequired,
  work: PropTypes.object.isRequired,
};

export default BottomNavigation;